@Service
public class PaymentService {

    @Autowired
    private PaymentRepository paymentRepository;

    @Autowired
    private IdempotencyRepository idempotencyRepository;

    @Autowired
    private PaymentGatewayClient gatewayClient;

    @Transactional
    public PaymentResponse processPayment(PaymentRequest request, String idempotencyKey) {
        // 1. Enforce Idempotency via Unique Constraint
        Optional<IdempotencyRecord> existing = idempotencyRepository.findByKey(idempotencyKey);
        if (existing.isPresent()) {
            if (existing.get().getStatus() == Status.COMPLETED) {
                return existing.get().getCachedResponse();
            }
            throw new DuplicateRequestException("Payment request is currently being processed");
        }

        IdempotencyRecord record = new IdempotencyRecord(idempotencyKey, Status.PROCESSING);
        idempotencyRepository.saveAndFlush(record);

        try {
            // 2. Persist initial PENDING state
            Payment payment = paymentRepository.save(new Payment(request, PaymentState.PENDING));

            // 3. Call external gateway (outside heavy DB locks if possible)
            GatewayResponse gatewayResponse = gatewayClient.charge(request);

            if (gatewayResponse.isSuccessful()) {
                payment.transitionTo(PaymentState.CAPTURED);
                payment.setGatewayTransactionId(gatewayResponse.getTransactionId());
            } else {
                payment.transitionTo(PaymentState.FAILED);
            }

            paymentRepository.save(payment);

            PaymentResponse response = PaymentResponse.from(payment);
            record.complete(response);
            idempotencyRepository.save(record);

            return response;
        } catch (Exception eheiten) {
            record.fail();
            idempotencyRepository.save(record);
            throw new PaymentProcessingException("Failed to process payment safely", e);
        }
    }
}
